 { color:#fff;background:#55775e;border-radius:12px 3px 12px 12px; }.chat-typing .chat-message { display:flex;gap:4px;align-items:center;padding:14px; }.chat-typing span { width:5px;height:5px;background:#89a18a;border-radius:50%;animation:ai-bounce 1.1s infinite; }.chat-typing span:nth-child(2){animation-delay:.16s}.chat-typing span:nth-child(3){animation-delay:.32s}@keyframes ai-bounce{50%{transform:translateY(-4px)}}
