<script>
(() => {
  const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '{{ csrf_token() }}';
  const chatForm = document.getElementById('chatForm'), chatInput = document.getElementById('chatInput'), chatFeed = document.getElementById('chatFeed'), chatSend = document.getElementById('chatSend'), chatError = document.getElementById('chatError'), conversationList = document.getElementById('conversationList'), newChat = document.getElementById('newChat');
  let conversationId = null;
  const showError = (el, message) => { el.textContent = message; el.classList.add('visible'); };
  const clearError = el => { el.textContent = ''; el.classList.remove('visible'); };
  const addMessage = (role, text) => { const row = document.createElement('div'); row.className = `chat-bubble ${role === 'user' ? 'user' : ''}`; const avatar = document.createElement('span'); avatar.className = 'chat-avatar'; avatar.innerHTML = role === 'user' ? '<i class="fas fa-user"></i>' : '<i class="fas fa-robot"></i>'; const message = document.createElement('div'); message.className = 'chat-message'; message.textContent = text; row.append(avatar, message); chatFeed.append(row); chatFeed.scrollTop = chatFeed.scrollHeight; return row; };
  chatInput.addEventListener('keydown', event => { if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) { event.preventDefault(); chatForm.requestSubmit(); } });
  const welcome = () => { chatFeed.innerHTML = ''; addMessage('assistant', 'Hi {{ $user->name }}! I can help draft website copy, patient communications, social posts, checklists, and more. What would you like to create?'); };
  const setActive = id => document.querySelectorAll('.conversation-item').forEach(item => item.classList.toggle('active', String(id) === item.dataset.conversationId));
  const addConversation = conversation => { let item = document.querySelector(`.conversation-item[data-conversation-id="${conversation.id}"]`); if (!item) { item = document.createElement('button'); item.type = 'button'; item.className = 'conversation-item'; item.dataset.conversationId = conversation.id; item.innerHTML = '<i class="far fa-comment"></i><span></span>'; conversationList.prepend(item); document.getElementById('historyEmpty')?.remove(); } item.title = conversation.title; item.querySelector('span').textContent = conversation.title; return item; };
  const openConversation = async id => { if (!id || chatSend.disabled) return; clearError(chatError); try { const response = await fetch(conversationList.dataset.url.replace(':conversation', id), {headers:{'Accept':'application/json'}}); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Unable to load this chat.'); conversationId = data.conversation.id; chatFeed.innerHTML = ''; data.conversation.messages.forEach(message => addMessage(message.role, message.content)); setActive(conversationId); } catch (error) { showError(chatError, error.message || 'Unable to load this chat.'); } };
  conversationList.addEventListener('click', event => { const item = event.target.closest('.conversation-item'); if (item) openConversation(item.dataset.conversationId); });
  newChat.addEventListener('click', () => { if (chatSend.disabled) return; conversationId = null; clearError(chatError); welcome(); setActive(null); chatInput.focus(); });
  chatForm.addEventListener('submit', async event => { event.preventDefault(); const message = chatInput.value.trim(); if (!message || chatSend.disabled) return; clearError(chatError); addMessage('user', message); chatInput.value = ''; chatSend.disabled = true; const typing = document.createElement('div'); typing.className = 'chat-bubble chat-typing'; typing.innerHTML = '<span class="chat-avatar"><i class="fas fa-robot"></i></span><div class="chat-message"><span></span><span></span><span></span></div>'; chatFeed.append(typing); chatFeed.scrollTop = chatFeed.scrollHeight; try { const response = await fetch('{{ route('user.ai-studio.chat') }}', { method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf}, body:JSON.stringify({message, conversation_id:conversationId}) }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Something went wrong.'); typing.remove(); addMessage('assistant', data.reply); conversationId = data.conversation.id; addConversation(data.conversation); setActive(conversationId); } catch (error) { typing.remove(); showError(chatError, error.message || 'Unable to send your message.'); } finally { chatSend.disabled = false; chatInput.focus(); } });
  document.querySelectorAll('.quick-prompt').forEach(button => button.addEventListener('click', () => { chatInput.value = button.dataset.prompt; chatInput.focus(); }));
  const imageCreate = document.getElementById('imageCreate'), imagePrompt = document.getElementById('imagePrompt'), imageError = document.getElementById('imageError'), imageResult = document.getElementById('imageResult'), generatedImage = document.getElementById('generatedImage'), imageDownload = document.getElementById('imageDownload');
  imageCreate.addEventListener('click', async () => { const prompt = imagePrompt.value.trim(); if (!prompt || imageCreate.disabled) { if (!prompt) showError(imageError, 'Describe the image you would like to create.'); return; } clearError(imageError); imageCreate.disabled = true; imageCreate.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Creating…'; try { const response = await fetch('{{ route('user.ai-studio.image') }}', { method:'POST', headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf}, body:JSON.stringify({prompt, size:document.getElementById('imageSize').value}) }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Image generation failed.'); generatedImage.src = data.image; imageDownload.href = data.image; imageDownload.download = data.filename; imageResult.classList.add('visible'); } catch (error) { showError(imageError, error.message || 'Unable to create an image.'); } finally { imageCreate.disabled = false; imageCreate.innerHTML = '<i class="fas fa-magic"></i> Create image'; } });
})();
</script>
